import { ChevronLeft, ChevronRight, Crown, Sparkles } from 'lucide-react';
import { motion } from 'framer-motion';

const portraitFrameStyle = {
  background:
    'radial-gradient(circle at top, rgba(255,255,255,0.16) 0%, rgba(255,255,255,0.06) 42%, rgba(10,10,10,0.72) 100%)',
};

const portraitImageStyle = {
  objectFit: 'contain',
  objectPosition: 'center center',
  filter: 'brightness(1.12) saturate(1.08) contrast(1.03)',
};

export default function HeroCarousel({
  items = [],
  currentIndex = 0,
  currentItem = null,
  onPrev,
  onNext,
  onOpen,
  onSelect,
  paused = false,
  onHoverChange,
  autoplayMs = 5000,
}) {
  if (!currentItem || items.length === 0) return null;

  const previewIndexes = Array.from({ length: Math.min(items.length, 5) }, (_, offset) => {
    const start = Math.max(0, Math.min(items.length - Math.min(items.length, 5), currentIndex - 2));
    return start + offset;
  });

  return (
    <div
      className="relative overflow-hidden rounded-[28px] border border-white/10 bg-white/5 p-6 shadow-2xl backdrop-blur-xl"
      onMouseEnter={() => onHoverChange?.(true)}
      onMouseLeave={() => onHoverChange?.(false)}
    >
      <div
        className="absolute inset-0 opacity-70"
        style={{
          background:
            'radial-gradient(circle at top right, rgba(212,160,83,0.16), transparent 42%), linear-gradient(135deg, rgba(10,14,25,0.42), rgba(20,24,36,0.72))',
        }}
      />

      <div className="relative z-10 flex items-center justify-between gap-4">
        <div className="inline-flex items-center gap-2 rounded-full border border-amber-300/15 bg-amber-400/10 px-4 py-2 text-[11px] font-black uppercase tracking-[0.24em] text-amber-200">
          <Sparkles size={14} />
          Sân khấu danh nhân
        </div>
        <div className="inline-flex items-center gap-2 rounded-full border border-white/10 bg-slate-950/60 px-4 py-2 text-sm font-black text-white">
          <span className="text-amber-300">{String(currentIndex + 1).padStart(2, '0')}</span>
          <span className="text-white/30">/</span>
          <span className="text-white/60">{String(items.length).padStart(2, '0')}</span>
        </div>
      </div>

      <div className="relative z-10 mt-6 grid gap-6 xl:grid-cols-[minmax(0,1fr)_220px] xl:items-end">
        <div className="relative">
          <button
            type="button"
            onClick={onPrev}
            className="absolute left-4 top-1/2 z-20 hidden h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-slate-950/70 text-white transition hover:border-amber-300/40 hover:text-amber-200 xl:flex"
            aria-label="Danh nhân trước"
          >
            <ChevronLeft size={20} />
          </button>

          <motion.button
            key={currentItem.id}
            type="button"
            onClick={onOpen}
            initial={{ opacity: 0, y: 18, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.45, ease: 'easeOut' }}
            className="group relative w-full overflow-hidden rounded-[32px] border border-amber-300/20 p-5 text-left transition hover:border-amber-300/40 hover:shadow-[0_0_48px_rgba(212,160,83,0.18)]"
            style={{
              background:
                'linear-gradient(135deg, rgba(212,160,83,0.12) 0%, rgba(12,16,28,0.92) 38%, rgba(20,24,36,0.98) 100%)',
            }}
          >
            <div className="absolute inset-4 rounded-[26px] border border-white/10" />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_top,rgba(255,255,255,0.08),transparent_42%)] opacity-80" />
            <div className="relative flex flex-col gap-6">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <div className="text-xs font-black uppercase tracking-[0.24em] text-amber-300/80">
                    {currentItem.dynasty}
                  </div>
                  <h2 className="mt-3 text-4xl font-black text-white xl:text-5xl">
                    {currentItem.name}
                  </h2>
                  <p className="mt-3 max-w-2xl text-base leading-7 text-white/72">
                    {currentItem.description}
                  </p>
                </div>
                <div className="hidden shrink-0 rounded-2xl border border-white/10 bg-slate-950/60 px-4 py-3 text-right xl:block">
                  <div className="text-[10px] font-black uppercase tracking-[0.24em] text-white/40">
                    Kỷ nguyên
                  </div>
                  <div className="mt-2 text-lg font-black text-amber-200">{currentItem.era}</div>
                </div>
              </div>

              <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_220px]">
                <div className="grid gap-3 sm:grid-cols-3">
                  {currentItem.achievements.slice(0, 3).map((achievement) => (
                    <div
                      key={achievement}
                      className="rounded-2xl border border-white/10 bg-white/5 px-4 py-4"
                    >
                      <div className="text-[10px] font-black uppercase tracking-[0.24em] text-white/35">
                        Dấu ấn
                      </div>
                      <div className="mt-2 text-sm font-bold leading-6 text-white/92">{achievement}</div>
                    </div>
                  ))}
                </div>

                <div className="relative flex items-end justify-center">
                  <div className="absolute inset-0 rounded-[28px] bg-gradient-to-t from-black/35 to-transparent" />
                  <div className="relative w-full rounded-[28px] p-3" style={portraitFrameStyle}>
                    <img
                      src={currentItem.image}
                      alt={currentItem.name}
                      className="h-[360px] w-full rounded-[24px] transition duration-500 group-hover:scale-[1.02]"
                      style={{
                        ...portraitImageStyle,
                        boxShadow: '0 28px 72px rgba(0,0,0,0.55)',
                      }}
                    />
                  </div>
                  <div className="absolute left-4 top-4 inline-flex items-center gap-2 rounded-full bg-black/45 px-3 py-2 text-xs font-black uppercase tracking-[0.22em] text-amber-200 backdrop-blur-md">
                    <Crown size={14} />
                    {currentItem.title}
                  </div>
                </div>
              </div>
            </div>
          </motion.button>

          <button
            type="button"
            onClick={onNext}
            className="absolute right-4 top-1/2 z-20 hidden h-12 w-12 -translate-y-1/2 items-center justify-center rounded-full border border-white/10 bg-slate-950/70 text-white transition hover:border-amber-300/40 hover:text-amber-200 xl:flex"
            aria-label="Danh nhân kế tiếp"
          >
            <ChevronRight size={20} />
          </button>
        </div>

        <div className="grid gap-3">
          {previewIndexes.map((mappedIndex) => {
            const hero = items[mappedIndex];
            const active = mappedIndex === currentIndex;
            return (
              <button
                key={hero.id}
                type="button"
                onClick={() => onSelect?.(mappedIndex)}
                className={`rounded-2xl border px-4 py-4 text-left transition ${
                  active
                    ? 'border-amber-300/40 bg-amber-400/10 shadow-[0_0_24px_rgba(212,160,83,0.14)]'
                    : 'border-white/10 bg-white/5 hover:border-white/20 hover:bg-white/8'
                }`}
              >
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <div className="text-[10px] font-black uppercase tracking-[0.24em] text-white/35">
                      Danh nhân
                    </div>
                    <div className="mt-2 text-sm font-black text-white">{hero.name}</div>
                    <div className="mt-1 text-xs text-white/55">{hero.era}</div>
                  </div>
                  <div className="text-xs font-black text-amber-300">{String(mappedIndex + 1).padStart(2, '0')}</div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="relative z-10 mt-6">
        <div className="h-1.5 overflow-hidden rounded-full bg-white/8">
          <div
            key={`${currentItem.id}-${paused ? 'paused' : 'running'}`}
            className="hero-carousel-progress h-full rounded-full bg-gradient-to-r from-amber-300 via-amber-500 to-rose-500"
            style={{
              animationDuration: `${autoplayMs}ms`,
              animationPlayState: paused ? 'paused' : 'running',
            }}
          />
        </div>
      </div>
    </div>
  );
}
